package com.codeguardian.service; import com.codeguardian.dto.*; import com.codeguardian.entity.*; import com.codeguardian.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.List; @Service @RequiredArgsConstructor public class RoleService{private final RoleRepository roles; private final RolePermissionRepository links; private final PermissionRepository permissions; public List<Role> getAllRoles(){return roles.findAll();} public List<RoleDTO> getAllRolesWithPermissions(){return roles.findAll().stream().map(this::dto).toList();} public RoleDTO getRoleById(Long id){return dto(roles.findById(id).orElseThrow());} private RoleDTO dto(Role r){return RoleDTO.builder().id(r.getId()).code(r.getCode()).name(r.getName()).description(r.getDescription()).status(r.getStatus()).permissions(links.findPermissionCodesByRoleId(r.getId())).build();} @Transactional public RoleDTO createRole(RoleCreateDTO d){if(roles.existsByCode(d.getCode()))throw new IllegalArgumentException("Role code already exists"); Role r=roles.save(Role.builder().code(d.getCode()).name(d.getName()).description(d.getDescription()).status(d.getStatus()).createdAt(LocalDateTime.now()).build()); if(d.getPermissionCodes()!=null)assignPermissions(r.getId(),d.getPermissionCodes()); return dto(r);} @Transactional public RoleDTO updateRole(Long id,RoleUpdateDTO d){Role r=roles.findById(id).orElseThrow(); if(d.getName()!=null)r.setName(d.getName()); if(d.getDescription()!=null)r.setDescription(d.getDescription()); if(d.getStatus()!=null)r.setStatus(d.getStatus()); roles.save(r); if(d.getPermissionCodes()!=null)assignPermissions(id,d.getPermissionCodes()); return dto(r);} @Transactional public void deleteRole(Long id){if(!roles.existsById(id))throw new IllegalArgumentException("Role not found"); links.deleteByRoleId(id); roles.deleteById(id);} @Transactional public void assignPermissions(Long id,List<String> codes){links.deleteByRoleId(id); for(String c:codes){Permission p=permissions.findByCode(c).orElseThrow(); links.save(RolePermission.builder().roleId(id).permissionId(p.getId()).createdAt(LocalDateTime.now()).build());}}}
